```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class FileDownloadServlet extends HttpServlet {

    private static final String BASE_DIR = "/var/www/files";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String filename = req.getParameter("file");

        // 校验文件名是否合法
        if (filename == null || filename.trim().isEmpty()) {
            resp.sendError(400, "Invalid file name");
            return;
        }

        // 禁止路径穿越
        if (filename.contains("..") || filename.contains("/") || !filename.matches("^[a-zA-Z0-9_\-\.]++$")) {
            resp.sendError(400, "Invalid file name");
            return;
        }

        File file = new File(BASE_DIR + "/" + filename);
        if (!file.exists()) {
            resp.send,sendError(404);
            return;
        }

        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] buf = fis.readAllBytes();
            resp.getOutputStream().write(buf);
        }
    }
}
